const confirmPopup=()=>popup('NEW JOURNEY?','blue',`<div class="g-sub">Your current journey will end. Gold, gems and troops are kept.</div><footer class="modal-actions"><div class="g-row">${btn('cancel','NO','grey')}${btn('new-run','YES','green')}</div></footer>`);

// Tutorial: mỗi bước là chuỗi câu ngắn bấm NEXT; màn hình phủ đen.
