let stageTipDismissed=false,hintTimer=0,shownLesson='',shownGuide='',tipPage=0,coachHold=false;
function currentStep():LessonStep|null{if(brushInspect||screen==='summon'||(screen==='battle'&&battle))return null;const seen=save.tutorial;if(!seen.ftue)return firstLesson({screen,seen,preparing,hasPool:!!pool,valid:!!pool?.valid,battling:!!battle});if(menuLessons[screen]&&!seen[screen+'Intro']&&!detail&&!brushDetail&&!pulls.length&&!brushPulls.length)return {id:screen+'Intro',pages:[menuLessons[screen]],passive:true,autoHide:7000};if(screen==='battle'&&!battle&&!preparing&&!stageTipDismissed)return contextLesson(currentMap,seen);return null;}
function coach(){const step=currentStep();if((step?.id||'')!==shownLesson){clearTimeout(hintTimer);hintTimer=0;shownLesson=step?.id||'';}const guide=step?.guide&&pool?currentMap.id:'';if(guide!==shownGuide){shownGuide=guide;stage.setGuide(guide?currentMap.referenceSolution[0].map(([x,y])=>({x,y})):null);}ui.querySelector('.tut')?.remove();const hint=ui.querySelector<HTMLElement>('#g-hint');if(!step){if(hint)hint.style.visibility='';return;}if(hint&&!pool?.error)hint.style.visibility='hidden';const box=document.createElement('div'),page=step.pages[0],text=typeof page==='string'?page:page[0];box.className='tut tut-passive';box.innerHTML=`<div class="lesson-card"><span class="lesson-mark">${step.guide?icon.brush:icon.spark}</span><p>${text}</p><button data-action="tip-ok" data-id="${step.id}" aria-label="Dismiss hint">${icon.close}</button></div>`;ui.append(box);if(step.autoHide&&!hintTimer){const id=step.id;hintTimer=window.setTimeout(()=>{hintTimer=0;if(shownLesson!==id)return;save.tutorial[id]=true;if(screen==='battle'&&!id.startsWith('f-')&&id!=='ftueBattle')stageTipDismissed=true;persist();coach();},step.autoHide);}}
function render(){screen==='battle'?renderBattle():renderMenu();}
let disposeSummonCarousel=()=>{};
function renderMenu(){disposeSummonCarousel();delete canvas.dataset.presentation;const testDetailsOpen=!!ui.querySelector<HTMLDetailsElement>('.test-details')?.open;let app=document.querySelector<HTMLElement>('#app')!;const scroll=screen==='brushes'&&app.dataset.screen===screen&&!workshopAtTop?(ui.querySelector('.g-body')?.scrollTop||0):0;app.dataset.screen=screen;labels.style.display='none';let html='';
 if(['home','squad','upgrade','summon','brushes'].includes(screen)){pool=null;battle=null;}
 if(screen==='home'){canvas.dataset.presentation='home';place('0','0',true);stage.renderer.setClearColor(0x000000,0);stage.load(maps[homeMap()],save.teams);html=homeScreen()+(confirm?confirmPopup():'');}
 else if(screen==='squad'){place('0','0',false);html=squadScreen();}
 else if(screen==='upgrade'){place('0','0',false);html=trainingScreen();}
 else if(screen==='summon'){place('0','0',false);html=summonScreen();}
 else if(screen==='brushes'){place('0','0',false);html=brushesScreen();}
 else html=({buff:buffPopup,result:resultPopup,runend:runEndPopup,event:eventPopup,shop:shopPopup} as Record<string,()=>string>)[screen]?.()||'';
 ui.innerHTML=html;if(screen==='summon')disposeSummonCarousel=bindSummonCarousel(ui,()=>summonInfo||brushPulls.length>0||pulls.length>0);if(screen==='brushes'){const testDetails=ui.querySelector<HTMLDetailsElement>('.test-details');if(testDetails)testDetails.open=testDetailsOpen;ui.querySelector('.g-body')!.scrollTop=scroll;bindBrushPad(brushFocus,save.brushes[brushFocus]||1,brushTerrain);const rack=ui.querySelector<HTMLElement>('.brush-rack'),selected=rack?.querySelector<HTMLElement>('.selected');if(rack&&selected)rack.scrollLeft=Math.max(0,selected.offsetLeft-rack.offsetLeft-rack.clientWidth/2+selected.clientWidth/2);workshopAtTop=false;}addDebug();if(screen==='home')layoutHomeField();stage.resize();coach();}
function startMap(id:string){delete canvas.dataset.presentation;screen='battle';currentMap=maps[id];if(run().maps.length&&!save.tutorial.ftue){save.tutorial.ftue=true;persist();}lastValid=false;stageTipDismissed=false;battleEndAt=0;battle=null;grace=0;drawing=false;paused=false;active=0;cursor=null;let r=run();preparing=r.maps.length===0&&!!save.tutorial.ftue;if(!save.brushes[r.brush])r.brush=save.brush;pool=new InkPool(currentMap,r.goldInk,fxOf(r.brush));stage.load(currentMap,r.teams,r.extras.map(n=>n+(r.buffs.rb_extra_unit||0)));stage.setBrush(r.brush);labels.style.display='block';renderBattle();}
function avatars(){let r=run(),teams=currentMap.starts.length;return r.teams.slice(0,teams).map((team,t)=>`<div class="g-avteam team-${t}">${team.map((id,i)=>{let slot=t*3+i,hp=battle?battle.soldiers.filter(s=>s.team===0&&s.slot===slot):null,cur=hp?hp.reduce((n,s)=>n+Math.max(0,s.hp),0):1,max=hp?hp.reduce((n,s)=>n+s.maxHp,0):1;return `<div class="g-av ${rar(id)} ${battle&&cur<=0?'dead':''}"><img src="${portrait(id)}" alt=""><div class="hp"><i style="width:${Math.max(0,cur/max*100)}%"></i></div></div>`;}).join('')}</div>`).join('');}
function activeBrushPopup(){const id=run().brush,n=save.brushes[id]||1;return popup('JOURNEY BRUSH','blue',`${brushHero(id,n,true,true)}<div class="g-fx">${fxLines(id,n).map(line=>`<span>${line}</span>`).join('')}</div><footer class="modal-actions">${btn('close-active-brush','BACK TO BATTLE','big blue')}</footer>`);}
function renderBattle(){if(!pool)return;
 const app=document.querySelector<HTMLElement>('#app')!,combat=!!battle,two=pool.paths.length>1;
 app.dataset.screen='battle';app.dataset.phase=combat?'combat':'draw';
 stage.renderer.setClearColor(0x000000,0);
 place('88px',combat?'calc(100% - 192px - env(safe-area-inset-bottom, 0px))':'calc(100% - 236px - env(safe-area-inset-bottom, 0px))',true);
 labels.style.display='block';stage.resize();
 const bossBar=combat?`<div class="g-boss"><div class="row">${icon.boss}<span>${currentMap.name}</span></div><div class="g-bar red"><i id="g-bosshp"></i></div></div>`:`<div class="g-inkmeter" id="g-ink">${icon.ink}<div class="g-bar blue"><i id="g-inkfill"></i></div><b id="g-inknum"></b></div>${pool.goldBudget?`<div class="g-res g-gink">${icon.goldInk}<b id="g-goldnum">${Math.floor(pool.gold)}</b></div>`:''}`;
 const teamPick=two&&!combat?`<div class="g-teampick">${pool.paths.map((p,i)=>`<button class="g-tp team-${i}" data-action="team" data-team="${i}">${'AB'[i]}</button>`).join('')}</div>`:'';
 const brushBadge=`<button class="battle-brush" data-action="inspect-active-brush" aria-label="Inspect ${BR[run().brush].name}"><img src="${brushImage(run().brush)}" alt=""></button>`;
 const bottom=combat?`${btn('speed',`×${speed}`,'blue g-speed')}<div class="g-avatars ${two?'two-front':''}" id="g-avatars" aria-label="Your troops">${avatars()}</div><time id="g-time" aria-label="Battle time">0:00</time>`:`<div class="battle-loadout ${two?'two-front':''}">${brushBadge}<div class="g-avatars">${avatars()}</div></div><div class="g-actions">${btn('undo',icon.undo,'g-round')}${btn('reset',icon.reset,'g-round')}${btn('start','MARCH!','big shine',!pool.valid)}</div>`;
 ui.innerHTML=`<header class="g-hud">${btn('pause',icon.pause,'g-round')}${bossBar}${combat?'':`<div class="g-stagepill">${stageTag()} · ${currentMap.name}</div>`}</header>${teamPick}${combat?'':'<div class="g-hint" id="g-hint"></div><div class="g-forecast" id="g-forecast" hidden></div>'}<footer class="g-bottom">${bottom}</footer>${preparing&&!combat?preparePopup():''}${brushInspect?activeBrushPopup():''}`;
 addDebug();if(combat)updateBattleHud();else updateInk();coach();
}
function updateInk(){if(!pool)return;let ink=Math.max(0,pool.ink),fill=ui.querySelector<HTMLElement>('#g-inkfill'),num=ui.querySelector('#g-inknum'),meter=ui.querySelector('#g-ink'),gold=ui.querySelector('#g-goldnum');if(fill)fill.style.width=Math.min(100,ink/currentMap.baseInk*100)+'%';if(num)num.innerHTML=`${Math.floor(ink)}<small>+${Math.floor(ink*C.inkToXp*(1+runValue(run(),'rb_frugal')))} XP</small>`;meter?.classList.toggle('low',ink<currentMap.baseInk*.15);if(gold)gold.textContent=String(Math.floor(pool.gold));
 let path=pool.paths[active],start=ui.querySelector<HTMLButtonElement>('[data-action=start]');if(start)start.disabled=!pool.valid;for(const a of ['undo','reset']){let b=ui.querySelector<HTMLButtonElement>(`[data-action=${a}]`);if(b)b.disabled=!path.points.length;}
 ui.querySelectorAll<HTMLElement>('.g-tp').forEach((b,i)=>{b.classList.toggle('on',i===active);b.classList.toggle('ok',pool!.paths[i].valid);b.textContent='AB'[i]+(pool!.paths[i].valid?' ✓':'');});
 let hint=ui.querySelector<HTMLElement>('#g-hint');if(hint){let err=pool.error,two=pool.paths.length>1,next=pool.paths.findIndex(p=>!p.valid),text=err?err:pool.valid?'':grace?'Touch the tip to keep drawing!':two&&path.valid&&next>=0?`Now draw squad ${'AB'[next]}`:!path.points.length&&currentMap.chapter===1?(two?`Drag from flag ${'AB'[active]} to a boss`:'Draw from START to the boss. Camps earn stars.'):'';hint.textContent=text;hint.className='g-hint '+(err?'err':pool.valid?'ok':'');hint.style.display=text&&!drawing?'':'none';const lesson=ui.querySelector<HTMLElement>('.tut-passive');if(lesson)lesson.style.display=err||grace||drawing?'none':'';hint.style.visibility=err||grace?'':lesson?'hidden':'';}
 stage.ribbon(pool);queueForecast();if(pool.valid!==lastValid){lastValid=pool.valid;if(lastValid){const goal=pool.paths[active].points.at(-1)!;stage.juice.burst(goal.x,stage.elevation(goal)+12,goal.y,'loot');stage.sound.play('heal');}coach();}}
let lastValid=false,forecastTimer=0,forecastKey='';
// Mô phỏng nhanh trận đánh ngay khi đường hợp lệ để báo trước thắng/thua
function queueForecast(){clearTimeout(forecastTimer);const box=ui.querySelector<HTMLElement>('#g-forecast');if(!box||!pool)return;if(!pool.valid){box.hidden=true;forecastKey='';return;}const key=pool.paths.map(p=>p.points.length+':'+Math.round(p.spent)).join('|')+run().brush;if(key===forecastKey&&!box.hidden)return;forecastKey=key;box.hidden=false;box.className='g-forecast wait';box.innerHTML='<b>Forecast…</b>';const myKey=key;forecastTimer=window.setTimeout(()=>{if(!pool?.valid)return;const b=new Battle(currentMap,pool,run(),save,false);const slice=()=>{if(forecastKey!==myKey||screen!=='battle'||battle)return;const t0=performance.now();while(!b.result&&b.time<=C.battleTimeoutSec+1&&performance.now()-t0<10)b.step(1/60);if(!b.result&&b.time<=C.battleTimeoutSec+1){requestAnimationFrame(slice);return;}done(b);};slice();},250);
 const done=(b:Battle)=>{const alive=b.soldiers.filter(s=>s.team===0&&s.hp>0).length,total=b.soldiers.filter(s=>s.team===0).length,win=b.result==='win',close=win&&alive<total*.35,starsN=win?Math.min(3,b.campsDestroyed+Math.max(0,3-currentMap.camps.length)):0;box.className='g-forecast '+(win?close?'close':'win':'loss');box.innerHTML=`<b>${win?close?'CLOSE FIGHT':'LIKELY WIN':'LIKELY LOSS'}</b><span>${win?`${alive}/${total} troops left`:`${b.bosses.filter(x=>x.hp>0).length?'boss survives':'army falls'}`}</span><span class="st">${stars(starsN)}</span>`;if(save.tutorial.ftue&&!save.tutorial.forecast)coach();};}
function powerChip(m:MapData){const need=m.starts.length,have=armyPower(save.levels,save.teams,need),rec=recommendedPower(m),cls=have>=rec?'ok':have>=rec*.85?'mid':'low';return `<div class="g-power ${cls}">${icon.tabBattle} Power <b>${have}</b> / ${rec} recommended</div>`;}
function advice(){const out:string[]=[],have=armyPower(save.levels,save.teams,currentMap.starts.length),rec=recommendedPower(currentMap);const up=Object.keys(U).filter(id=>canUpgrade(save,id));if(up.length)out.push(`▲ Level up <b>${up.map(id=>U[id].name).join(', ')}</b> in Training.`);else if(have<rec)out.push(`Your army is <b>${rec-have}</b> power short. Collect Gold and troop cards to level up.`);if(battle&&battle.enraged)out.push(`<b>${battle.enraged}</b> enemy squad(s) reached the boss. Destroy their camps first, or cross their route.`);const want=(currentMap as any).design?.threeStarBrush;if(currentMap.terrain.length&&want&&want!=='quill'&&!save.brushes[want])out.push(`A <b>${BR[want].name}</b> makes this terrain cheaper.`);if(!out.length)out.push('Try a route that grabs more charms before the boss.');return out;}
function updateBattleHud(){if(!battle)return;const hp=ui.querySelector<HTMLElement>('#g-bosshp'),cur=battle.bosses.reduce((n,b)=>n+Math.max(0,b.hp),0),max=battle.bosses.reduce((n,b)=>n+b.maxHp,0);if(hp)hp.style.width=Math.max(0,cur/max*100)+'%';const time=ui.querySelector('#g-time'),seconds=Math.floor(battle.time);if(time)time.textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');const av=ui.querySelector('#g-avatars');if(av)av.innerHTML=avatars();}
function advance(){run().layer++;persist();proceed();}
function stages(){return chapterStages(run().chapter);}
function stageTag(){let list=stages().slice(0,run().layer+1).filter(id=>maps[id]);return `Stage ${list.length}/${stages().filter(id=>maps[id]).length}`;}
function proceed(){offers=[];battle=null;let r=run();if(r.ended){lastResult={clear:false};screen='runend';}else if(r.picks>0){screen='buff';offers=weightedBuffs(r);}else if(r.layer>=stages().length)screen='runend';else{let id=stages()[r.layer];if(id==='shop'){screen='shop';offers=weightedBuffs(r);rerolls=0;}else if(id.startsWith('event:')){screen='event';eventId=id.slice(6);}else{startMap(id);return;}}render();}
function xpAdd(xp:number){let r=run();r.xp+=xp;while(r.level<C.runLevelXp.length&&r.xp>=C.runLevelXp[r.level]){r.xp-=C.runLevelXp[r.level];r.level++;r.picks++;}}
function finish(forced?:boolean){if(!battle||!pool||screen!=='battle')return;drawing=false;grace=0;cursor=null;let win=forced??battle.result==='win',r=run();if(!win){r.ended=true;lastResult={win:false};screen='result';persist();render();return;}
 let last=stages().slice(r.layer+1).every(id=>!maps[id]),type:'battle'|'boss'=last?'boss':'battle';let ink=Math.floor(pool.ink)+battle.lootInk,inkXp=Math.floor(ink*C.inkToXp*(1+runValue(r,'rb_frugal'))),xp=inkXp+C.battleXp[type],coins=Math.floor(C.battleCoins[type]*(1+runValue(r,'rb_golden_touch')))+battle.lootCoins;let camps=battle.campsDestroyed,starCount=Math.min(3,camps+Math.max(0,3-currentMap.camps.length));let opened=currentMap.items.filter((o,i)=>o.type==='chest'&&battle!.collected.has(i)).length;
 let before=save.stars[currentMap.id]||0,gems=Math.max(0,starCount-before)*C.gemsPerStar+(save.cleared[currentMap.id]?0:C.gemsFirstClear);save.cleared[currentMap.id]=true;let gold=C.battleGold[type]+Math.max(0,starCount-before)*10;save.stars[currentMap.id]=Math.max(starCount,before);save.gold+=gold;r.earned+=gold;r.coins+=coins;r.maps.push(currentMap.id);r.goldInk=pool.gold;r.nextHp=1;r.bonus=false;r.picks+=opened;xpAdd(xp);
 if(currentMap.goldZones.length){xpAdd(Math.floor(r.goldInk*C.goldInkToXp));r.goldInk=0;}
 if(last){if(r.picks){gems+=r.picks*C.gemsPerPick;r.picks=0;}let key='chapter'+r.chapter;if(!save.cleared[key]){gems+=C.gemsChapterClear;save.cleared[key]=true;}save.chapter=Math.max(save.chapter,Math.min(chapters.length,r.chapter+1));let clear=C.runClearGold[Math.min(C.runClearGold.length-1,r.chapter-1)];save.gold+=clear;r.earned+=clear;}
 if(currentMap.id==='c1_s1'){save.tutorial.ftue=true;save.tutorial.ftueBattle=true;}save.gems+=gems;lastResult={win,stars:starCount,camps,ink,inkXp,xp,coins,gold,gems,clear:last};r.layer++;screen='result';persist();render();}
